   279	    private void addAllNonRedefined(Set<MappingOptions> inheritedMappings) {
   280	        // We are only adding the targets here since this mappings have already been reversed
   281	        Set<String> redefinedTargets = new HashSet<>();
   282	        for ( MappingOptions redefinedMappings : mappings ) {
   283	            if ( redefinedMappings.getTargetName() != null ) {
   284	                redefinedTargets.add( redefinedMappings.getTargetName() );
