        TypeElement usedMapper = usedMapperType.getTypeElement();
        for ( ExecutableElement executable : elementUtils.getAllEnclosedExecutableElements( usedMapper ) ) {
            SourceMethod method = getMethod(
                usedMapperType,
                executable,
                mapperToImplement,
                mapperOptions,
                prototypeMethods );

            if ( method != null ) {
                methods.add( method );
