        if ( restrictToDefinedMappings != that.restrictToDefinedMappings ) {
            return false;
        }
        if ( forForgedMethods != that.forForgedMethods ) {
            return false;
        }
        if ( !Objects.equals( mappingReferences, that.mappingReferences ) ) {
            return false;
        }

        return true;
    }

